 function render(){const s=lines[index];if(!s){finish();return} $('chapter').textContent=s.chapter;$('speaker').textContent=s.speaker;$('speaker').className='nameplate '+(s.speaker==='Story'?'narrator':s.speaker==='Garfiel'?'garfiel':'');$('line').innerHTML=s.text.replace(/(warm|lovely|together)/gi,'<em>$1</em>');
  const ram=$('ram'),garf=$('garfiel');ram.classList.toggle('show',s.who==='ram'||s.who==='both');ram.classList.toggle('is-hidden',!(s.who==='ram'||s.who==='both'));garf.classList.toggle('show',s.who==='garfiel'||s.who==='both');garf.classList.toggle('is-hidden',!(s.who==='garfiel'||s.who==='both'));
  const c=$('choices');c.innerHTML='';c.hidden=!s.choices;waiting=!!s.choices;$('continue').style.visibility=waiting?'hidden':'visible';if(s.choices){s.choices.forEach(([label,target,points])=>{const b=document.createElement('button');b.className='choice';b.textContent=label;b.onclick=e=>{e.stopPropagation();score+=points;index=nextById(target);render()};c.appendChild(b)})}
  const sceneNum=s.chapter.startsWith('Prologue')?0:s.chapter.startsWith('Chapter I')?1:2;$('progress').innerHTML=[0,1,2].map(n=>`<span class="${n<=sceneNum?'done':''}"></span>`).join('');save();}
-function advance(){if(waiting)return;index++;render()}
+function advance(){if(waiting)return;const current=lines[index];index=current.next?nextById(current.next):index+1;render()}
 function save(){try{localStorage.setItem('petals-save',JSON.stringify({index,score}))}catch(e){}}
 function begin(){ $('intro').classList.add('off');index=0;score=0;render()}
 function finish(){waiting=true;$('choices').hidden=true;$('continue').style.visibility='hidden';$('dialogue').style.opacity='.18';$('dialogue').style.pointerEvents='none';$('ram').classList.add('show');$('garfiel').classList.add('show');let high=score>=2;$('endTitle').textContent=high?'A promise beneath the lanterns':'A flower for the road';$('endText').textContent=high?'Ram’s fingers curled around his, just for a moment. “Tomorrow, then,” she said. Garfiel grinned like the whole winter had turned to spring. Whatever this feeling was, they could discover it side by side.':'Ram tucked the flower safely into her hair. Garfiel walked her home through the snow, close enough to share the lantern light. Their teasing continued—but now it carried the warmth of a promise not yet spoken.';$('ending').style.display='block';localStorage.removeItem('petals-save')}
 $('beginBtn').onclick=begin;$('dialogue').onclick=advance;$('dialogue').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();advance()}};$('againBtn').onclick=()=>{index=0;score=0;$('ending').style.display='none';$('dialogue').style.opacity='1';$('dialogue').style.pointerEvents='auto';render()};$('restartBtn').onclick=()=>{if(confirm('Restart the story from the beginning?')){index=0;score=0;$('ending').style.display='none';$('dialogue').style.opacity='1';$('dialogue').style.pointerEvents='auto';render()}};

